<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api } from '../services/api'
import { useSessionStore } from '../stores/session'
import { useMetaStore } from '../stores/meta'
import { useUiStore } from '../stores/ui'
import { useRouter } from 'vue-router'
import SingleSelectSheet from '../components/SingleSelectSheet.vue'
import MultiFilterSheet from '../components/MultiFilterSheet.vue'
import { copyText } from '../utils/clipboard'
import { useBrowserNotificationsStore } from '../stores/browserNotifications'

const session=useSessionStore(),meta=useMetaStore(),ui=useUiStore(),router=useRouter()
const browserNotifications=useBrowserNotificationsStore()
const notification=ref(null),manager=ref(''),saving=ref(false),exporting=ref(false)
const managerSheet=ref(false),filterSheet=ref('')
const form=reactive({enabled:false,dialogFilter:'unanswered',managerFilters:[],statuses:[],queueAlerts:true,violationMinutes:20,workDays:[1,2,3,4,5,6,7],slaMinutes:8,workStart:'10:00',workEnd:'22:00',repeatMinutes:0,timezone:'Europe/Moscow'})
const managers=computed(()=>session.isAdmin?meta.users.map(u=>u.name||u.login):[session.account?.name||session.loginName].filter(Boolean))
const managerOptions=computed(()=>managers.value.map(m=>({value:m,label:m})))
const statusOptions=computed(()=>meta.statuses.map(s=>({value:s.name||s,label:s.name||s})))
const botConfigured=computed(()=>!!notification.value?.botConfigured)
const backgroundReady=computed(()=>!!notification.value?.internalSchedulerConfigured)
function selectedRule(){return notification.value?.rules?.find(r=>r.manager===manager.value)}
function syncRule(){const r=selectedRule();Object.assign(form,{enabled:!!r?.enabled,dialogFilter:r?.dialogFilter||'unanswered',managerFilters:r?[...(r.managerFilters||[])]:(manager.value?[manager.value]:[]),statuses:[...(r?.statuses||[])],queueAlerts:r?.queueAlerts!==false,violationMinutes:Number(r?.violationMinutes||20),workDays:[...(r?.workDays||[1,2,3,4,5,6,7])],slaMinutes:Number(r?.slaMinutes||8),workStart:r?.workStart||'10:00',workEnd:r?.workEnd||'22:00',repeatMinutes:Number(r?.repeatMinutes||0),timezone:r?.timezone||'Europe/Moscow'})}
function chooseManager(value){manager.value=value;syncRule()}
async function load(){await meta.load();notification.value=await api.notificationSettings();manager.value=manager.value||managers.value[0]||'';syncRule()}
async function save(){if(!form.workDays.length)return ui.toast('Выберите хотя бы один рабочий день','error');saving.value=true;try{await api.saveNotificationSettings({manager:manager.value,...form,timezone:'Europe/Moscow'});ui.toast('Настройки уведомлений сохранены','ok');await load()}catch(e){ui.toast(e.message,'error')}finally{saving.value=false}}
async function pair(){if(!botConfigured.value)return ui.toast('Сначала добавьте TELEGRAM_BOT_TOKEN в Render Environment','error',7000);try{const d=await api.pairTelegram(manager.value);window.open(d.pairUrl,'_blank','noopener');ui.toast(`Откройте @${d.botUsername||notification.value?.botUsername} и нажмите START`,'ok',7000)}catch(e){ui.toast(e.message,'error',7000)}}
async function test(){try{await api.testTelegram(manager.value);ui.toast('Тест отправлен в Telegram','ok')}catch(e){ui.toast(e.message,'error')}}
async function exportRules(){exporting.value=true;try{const d=await api.exportNotificationRules();if(!d.count)return ui.toast('Сначала подключите Telegram хотя бы одного менеджера','error',7000);await copyText(d.value);ui.toast(`Скопировано подключений: ${d.count}. Вставьте значение в Render как NOTIFICATION_RULES_JSON`,'ok',9000)}catch(e){ui.toast(e.message,'error',7000)}finally{exporting.value=false}}
async function enableBrowserNotifications(){try{await browserNotifications.enable();ui.toast('Браузерные уведомления включены','ok')}catch(e){ui.toast(e.message,'error',7000)}}
async function testBrowserNotifications(){try{await browserNotifications.test();ui.toast('Тестовое уведомление отправлено','ok')}catch(e){ui.toast(e.message,'error',7000)}}
async function logout(){await session.logout();router.replace('/dialogs')}
onMounted(()=>load().catch(e=>ui.toast(e.message,'error')))
const databaseSyncing=ref(false)
async function syncDatabase(){databaseSyncing.value=true;try{const d=await api.syncDatabase();ui.toast(`Сохранено карточек: ${d.clients}`,'ok')}catch(e){ui.toast(e.message,'error')}finally{databaseSyncing.value=false}}
</script>
<template>
  <main class="page page-with-nav">
    <header class="page-header sticky-header"><div><small>SEB_GUN CRM</small><h1>Ещё</h1></div><button class="header-action" @click="ui.toggleTheme()">{{ui.theme==='dark'?'☀':'☾'}}</button></header>
    <section class="settings-card"><h3>Аккаунт</h3><div class="setting-row"><span>BlueSales</span><b>{{session.account?.name||session.loginName}}</b></div><div class="setting-row"><span>VK</span><b>{{session.vk?.groupName||'Подключён'}}</b></div><div class="setting-row"><span>Версия</span><b>v28.16 Vue</b></div><div class="setting-row timezone-row"><span>Время проекта</span><b>Москва (МСК)</b></div></section>
    <section v-if="session.isAdmin" class="settings-card admin-entry"><div><h3>Админка</h3><p>Быстрые фразы, пользователи, CRM-статусы и журнал уведомлений.</p></div><button class="primary-btn" @click="router.push('/admin/phrases')">Открыть админку</button></section>
    <section class="settings-card browser-alert-settings"><h3>Уведомления браузера</h3><p>CRM проверяет лиды раз в минуту и показывает системное уведомление, пока сайт или установленное PWA открыты, в том числе в свёрнутой вкладке.</p><div class="setting-row"><span>Поддержка браузером</span><b :class="browserNotifications.supported?'connected-text':'muted-text'">{{browserNotifications.supported?'Есть':'Нет'}}</b></div><div class="setting-row"><span>Разрешение</span><b :class="browserNotifications.permission==='granted'?'connected-text':'muted-text'">{{browserNotifications.permission==='granted'?'Разрешено':browserNotifications.permission==='denied'?'Запрещено':'Не запрошено'}}</b></div><div class="button-row"><button v-if="!browserNotifications.enabled" class="primary-btn" @click="enableBrowserNotifications">Включить уведомления браузера</button><button v-else class="secondary-btn" @click="browserNotifications.disable()">Выключить</button><button class="secondary-btn" :disabled="!browserNotifications.supported" @click="testBrowserNotifications">Отправить тест</button></div><small>Если полностью закрыть браузер или выключить устройство, проверка остановится. Для уведомлений при выключенных устройствах нужен серверный Telegram/Web Push и фоновый доступ к BlueSales.</small></section>
    <section class="settings-card notification-settings"><h3>Telegram и уведомления</h3><div v-if="notification&&!botConfigured" class="telegram-setup-warning"><b>Telegram-бот ещё не настроен на сервере</b><span>Добавьте секрет TELEGRAM_BOT_TOKEN в Render → Environment, сохраните и дождитесь нового запуска сервиса.</span><a href="https://dashboard.render.com/web/srv-daac5q67bikc7380t6m0/env" target="_blank" rel="noreferrer">Открыть Render Environment</a></div><div class="telegram-readiness"><div class="setting-row"><span>Токен бота</span><b :class="botConfigured?'connected-text':'muted-text'">{{botConfigured?'Настроен':'Не настроен'}}</b></div><div class="setting-row"><span>Фоновая проверка</span><b :class="backgroundReady?'connected-text':'muted-text'">{{backgroundReady?'Готова':'Нужны данные BlueSales'}}</b></div><div v-if="botConfigured" class="setting-row"><span>Бот</span><b>@{{notification.botUsername}}</b></div></div><p class="settings-hint">Сначала выберите, в чей Telegram отправлять уведомления, затем настройте фильтр лидов.</p><label>Получатель уведомлений<button type="button" class="select-sheet-trigger" @click="managerSheet=true"><span>{{manager||'Выберите менеджера'}}</span><b>▾</b></button></label><div class="setting-row"><span>Telegram получателя</span><b :class="selectedRule()?.telegramConnected?'connected-text':'muted-text'">{{selectedRule()?.telegramConnected?'Подключён':'Не подключён'}}</b></div><label class="toggle-row"><input v-model="form.enabled" type="checkbox"><span>Отправлять в Telegram, если лид долго без ответа</span></label><label class="toggle-row"><input v-model="form.queueAlerts" type="checkbox"><span>Отправлять в Telegram зависшие исходящие</span></label><div class="segmented"><button :class="{active:form.dialogFilter==='unanswered'}" @click="form.dialogFilter='unanswered'">Неотвеченные</button><button :class="{active:form.dialogFilter==='unread'}" @click="form.dialogFilter='unread'">Непрочитанные</button></div><div class="filter-buttons"><button type="button" @click="filterSheet='manager'"><span>Менеджеры лидов</span><b>{{form.managerFilters.length||'Все'}}</b><span>▾</span></button><button type="button" @click="filterSheet='status'"><span>CRM-статусы</span><b>{{form.statuses.length||'Все'}}</b><span>▾</span></button></div><label>Через сколько рабочих минут уведомить<input v-model.number="form.slaMinutes" type="number" min="1" max="240" step="1"></label><label>Нарушение — более, рабочих минут<input v-model.number="form.violationMinutes" type="number" min="1" max="1440"></label><div class="filter-buttons"><label v-for="(day,i) in ['Пн','Вт','Ср','Чт','Пт','Сб','Вс']" :key="day"><input v-model="form.workDays" type="checkbox" :value="i+1">{{day}}</label></div><div class="sla-preview">Лид появится в «Уведомлениях» и будет отправлен в Telegram через {{form.slaMinutes||8}} рабочих минут.</div><div class="form-grid"><label>Начало рабочего дня, МСК<input v-model="form.workStart" type="time"></label><label>Конец рабочего дня, МСК<input v-model="form.workEnd" type="time"></label></div><label>Повторить уведомление через, минут<input v-model.number="form.repeatMinutes" type="number" min="0" max="1440"><small>0 — не повторять</small></label><div class="setting-row timezone-row"><span>Часовой пояс</span><b>Europe/Moscow</b></div><button class="primary-btn" :disabled="saving||!manager" @click="save">Сохранить настройки</button><div class="button-row"><button class="secondary-btn" :disabled="!manager||!botConfigured" @click="pair">Подключить Telegram</button><button class="secondary-btn" :disabled="!manager||!selectedRule()?.telegramConnected" @click="test">Отправить тест</button></div></section>
    <section v-if="session.isAdmin" class="settings-card telegram-export"><h3>Сохранить подключения всех менеджеров</h3><p>После подключения менеджеров скопируйте конфигурацию и вставьте её в Render → Environment как <b>NOTIFICATION_RULES_JSON</b>.</p><div class="setting-row"><span>Постоянных подключений</span><b>{{notification?.durableRuleCount||0}}</b></div><button class="secondary-btn" :disabled="exporting" @click="exportRules">{{exporting?'Подготовка…':'Скопировать для Render'}}</button></section>
    <section v-if="session.isAdmin" class="settings-card"><h3>База данных</h3><p>Сохранить доступные этому аккаунту карточки BlueSales и даты следующих контактов в PostgreSQL.</p><button class="secondary-btn" :disabled="databaseSyncing" @click="syncDatabase">{{databaseSyncing?'Синхронизация…':'Синхронизировать клиентов'}}</button></section><section class="settings-card"><h3>Резерв</h3><p>Старый интерфейс v27 оставлен для отката и сравнения.</p><a class="secondary-btn link-btn" href="/legacy/">Открыть Legacy v27</a></section>
    <button class="danger-btn" @click="logout">Выйти</button>
  </main>
  <SingleSelectSheet :open="managerSheet" title="Менеджер" :options="managerOptions" :model-value="manager" empty-label="Выберите менеджера" @update:model-value="chooseManager" @close="managerSheet=false"/>
  <MultiFilterSheet :open="filterSheet==='manager'" title="Менеджеры лидов" :options="managerOptions" v-model="form.managerFilters" @apply="filterSheet=''" @close="filterSheet=''"/>
  <MultiFilterSheet :open="filterSheet==='status'" title="CRM-статусы лидов" :options="statusOptions" v-model="form.statuses" @apply="filterSheet=''" @close="filterSheet=''"/>
</template>
